templateScript:
// ===== Habit Tracker · A4 · TEMPLATES =====
const W = A4_WIDTH;    // 595
const H = A4_HEIGHT;   // 842
const M = 44;          // left/right margin
const CW = W - 2 * M;  // content width: 507

const INK = "#222222";
const MUTED = "#8a8a8a";
const RULE = "#c4c4c4";
const ACCENT = "#2e6b57";

// Base properties every element needs (spread first, then override)
const BASE = { rotation: 0, fill: "none", stroke: "none", strokeWidth: 0, opacity: 1 };

const rect = (id, x, y, w, h, extra = {}) =>
  ({ ...BASE, id, type: "rect", x, y, w, h, ...extra });

const txt = (id, text, x, y, w, h, extra = {}) => ({
  ...BASE, id, type: "text", x, y, w, h, text,
  fontSize: 12, fontFamily: "Inter", textColor: INK,
  fontWeight: "normal", fontStyle: "normal", textDecoration: "none",
  align: "left", verticalAlign: "middle", autoWidth: false,
  ...extra,
});

// ---------- MONTH PAGE: calendar, every date links to its day ----------
const GAP = 4;
const CELL_W = (CW - 6 * GAP) / 7;  // 69pt = ONE cell (7 cells + 6 gaps = content width)
const CELL_H = 100;                 // room for 6 week rows: 6*100 + 5*4 = 620pt
const CAL_Y = 174;

const monthEls = [
  txt("m_kicker", "HABIT TRACKER", M, 40, 300, 16, { fontSize: 10, fontWeight: "bold", textColor: ACCENT }),
  txt("m_title", "{{monthName}}", M, 58, 300, 56, { fontSize: 44, fontFamily: "Playfair Display", fontWeight: "bold" }),
  txt("m_year", "{{year}}", W - M - 160, 58, 160, 56, { fontSize: 44, fontFamily: "Playfair Display", textColor: MUTED, align: "right" }),
  txt("m_hint", "Tap a date to open that day.", M, 116, 300, 18, { fontSize: 11, fontStyle: "italic", textColor: MUTED }),
  rect("m_rule", M, 144, CW, 1.5, { fill: INK }),
];

// Weekday labels come from the month node's data, so the week start is set in one place
for (let c = 0; c < 7; c++) {
  monthEls.push(txt("m_wd" + c, "{{wd" + c + "}}", M + c * (CELL_W + GAP), 152, CELL_W, 18,
    { fontSize: 9, fontWeight: "bold", textColor: MUTED, align: "center" }));
}

monthEls.push({
  ...BASE,
  id: "m_calendar",
  type: "grid",
  x: M, y: CAL_Y, w: CELL_W, h: CELL_H,  // w/h are ONE cell
  fill: "#ffffff", stroke: "#9a9a9a", strokeWidth: 1,
  gridConfig: {
    cols: 7, gapX: GAP, gapY: GAP,
    sourceType: "current", sourceId: "",
    displayField: "day",                  // child.data.day -> "1", "2", ...
    offsetMode: "dynamic",
    offsetField: "startWeekday",          // blank cells before the 1st
    offsetAdjustment: 0,
    dataSliceStart: 0, dataSliceCount: 31,
    gridBorderMode: "all",
    gridBorderRadius: 6,
  },
});

// ---------- DAY PAGE: ten habit rows with tick boxes ----------
const ROWS = 10;
const ROW_TOP = 180;
const ROW_H = 50;            // rows run from 180 to 680
const BOX = 22;              // tick box size
const DONE_X = W - M - 50;   // 50pt "DONE" column on the right

const dayEls = [
  // Navigation
  txt("d_back", "‹ {{monthLabel}}", M, 28, 180, 24, { fontSize: 11, textColor: ACCENT, linkTarget: "parent" }),
  txt("d_prev", "{{prevLabel}}", W - M - 160, 28, 75, 24, { fontSize: 11, textColor: ACCENT, align: "center", linkTarget: "sibling", linkValue: "-1" }),
  txt("d_next", "{{nextLabel}}", W - M - 75, 28, 75, 24, { fontSize: 11, textColor: ACCENT, align: "center", linkTarget: "sibling", linkValue: "1" }),

  // Header
  txt("d_weekday", "{{weekday}}", M, 68, 340, 50, { fontSize: 38, fontFamily: "Playfair Display", fontWeight: "bold" }),
  txt("d_date", "{{dateLong}}", M, 118, 340, 22, { fontSize: 14, textColor: MUTED }),
  rect("d_rule", M, 154, CW, 1.5, { fill: INK }),

  // Column headings
  txt("d_col_habit", "HABIT", M + 30, 160, 200, 16, { fontSize: 8, fontWeight: "bold", textColor: MUTED }),
  txt("d_col_done", "DONE", DONE_X, 160, 50, 16, { fontSize: 8, fontWeight: "bold", textColor: MUTED, align: "center" }),
];

for (let i = 0; i < ROWS; i++) {
  const n = i + 1;
  const y = ROW_TOP + i * ROW_H;
  dayEls.push(
    rect("d_line" + n, M, y, CW, 0.75, { fill: RULE }),
    txt("d_num" + n, String(n), M, y, 22, ROW_H, { fontSize: 11, textColor: MUTED }),
    txt("d_habit" + n, "{{habit" + n + "}}", M + 30, y, CW - 90, ROW_H, { fontSize: 14 }),
    rect("d_box" + n, DONE_X + (50 - BOX) / 2, y + (ROW_H - BOX) / 2, BOX, BOX,
      { fill: "#ffffff", stroke: INK, strokeWidth: 1.2, borderRadius: 4 })
  );
}
dayEls.push(rect("d_line_end", M, ROW_TOP + ROWS * ROW_H, CW, 0.75, { fill: RULE }));

// Notes
dayEls.push(txt("d_notes", "NOTES", M, 700, 200, 14, { fontSize: 8, fontWeight: "bold", textColor: MUTED }));
[736, 766, 796].forEach((y, i) => dayEls.push(rect("d_note" + i, M, y, CW, 0.75, { fill: RULE })));

const templates = {
  tpl_month: { id: "tpl_month", name: "Month – Calendar", width: W, height: H, elements: monthEls },
  tpl_day: { id: "tpl_day", name: "Day – Habit Checklist", width: W, height: H, elements: dayEls },
};
return templates;

hierarchyScript:
// ===== Habit Tracker · November 2026 · HIERARCHY =====

// Your habits: printed on every day page (the first 10 are used).
// Use "" for any row you'd rather fill in by hand.
const HABITS = [
  "Wake up by 7:00",
  "Drink 2 L of water",
  "Exercise 30 min",
  "Read 20 pages",
  "Meditate 10 min",
  "5 portions of fruit & veg",
  "No sugary snacks",
  "Journal",
  "Walk 8,000 steps",
  "Screens off by 22:00",
];

const YEAR = 2026;
const MONTH = 10;      // 0-based: 10 = November
const WEEK_START = 1;  // 1 = Monday-first calendar, 0 = Sunday-first

const MONTHS = ["January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"];
const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const DAYS_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

const monthName = MONTHS[MONTH];
const monthLabel = `${monthName} ${YEAR}`;                   // "November 2026"
const daysInMonth = new Date(YEAR, MONTH + 1, 0).getDate();  // 30
// Blank calendar cells before the 1st. 1 Nov 2026 is a Sunday: 6 if Monday-first, 0 if Sunday-first.
const startWeekday = (new Date(YEAR, MONTH, 1).getDay() - WEEK_START + 7) % 7;

const nodes = {};
const rootId = createId("month");

// ---- Month page (root) ----
const monthData = { monthName, year: String(YEAR) };
for (let c = 0; c < 7; c++) monthData["wd" + c] = DAYS_SHORT[(c + WEEK_START) % 7];

nodes[rootId] = {
  id: rootId,
  parentId: null,
  type: "tpl_month",
  title: monthLabel,
  data: monthData,
  children: [],
};

// habit1 ... habit10, shared by every day page (" " prints as a blank row)
const habitData = {};
for (let i = 0; i < 10; i++) habitData["habit" + (i + 1)] = HABITS[i] || " ";

// ---- Day pages ----
for (let d = 1; d <= daysInMonth; d++) {
  const wd = new Date(YEAR, MONTH, d).getDay();
  const id = createId("day");
  nodes[id] = {
    id,
    parentId: rootId,
    type: "tpl_day",
    title: `${DAYS_SHORT[wd]} ${d} ${monthName.slice(0, 3)}`,  // "Sun 1 Nov"
    data: {
      day: String(d),                  // number shown in the calendar cell
      startWeekday,                    // read by the month grid from the first day
      weekday: DAYS[wd],               // "Sunday"
      dateLong: `${d} ${monthLabel}`,  // "1 November 2026"
      monthLabel,
      prevLabel: d > 1 ? `‹ ${DAYS_SHORT[(wd + 6) % 7]} ${d - 1}` : " ",
      nextLabel: d < daysInMonth ? `${DAYS_SHORT[(wd + 1) % 7]} ${d + 1} ›` : " ",
      ...habitData,
    },
    children: [],
  };
  nodes[rootId].children.push(id);
}

return { nodes, rootId };
